opts={"A":(4,3),"B":(5,4),"C":(3,2),"D":(24,12)}
base=[24,3,4,2,6,5,12]
def ev(v):
    a,b,c,d,e,f,g=v
    return a/b-c*d+e*f+g
res={}
for k,(p,q) in opts.items():
    v=[q if t==p else p if t==q else t for t in base]
    res[k]=ev(v)
assert res["D"]==50
for k in "ABC": assert res[k]!=50

